1	// Everything that depends on how TikTok's website is built lives in this file,
2	// so when TikTok changes its site there is one place to fix. Structure observed
3	// on tiktok.com on 2026-10-12.
4	
5	export interface CaptionTrack {
6	  url: string;
7	  language: string;
8	  format: string;
9	  autoGenerated: boolean;
10	  original: boolean;
11	}
12	
13	export interface TikTokVideo {
14	  id: string;
15	  author: string;
16	  description: string;
17	  hashtags: string[];
18	  onScreenText: string[];
19	  captionTracks: CaptionTrack[];
20	  noCaptionReason: number | null;
21	  aiLabel: { labeled: boolean; description: string };
22	}
23	
24	/** The script element where TikTok embeds each page's initial data. */
25	export const EMBEDDED_DATA_ELEMENT_ID = "__UNIVERSAL_DATA_FOR_REHYDRATION__";
26	
27	// Keep in sync with host_permissions in extension/manifest.json.
28	const CAPTION_DOMAINS = ["tiktok.com", "tiktokcdn.com", "tiktokcdn-us.com"];
29	
30	type Json = Record<string, unknown>;
31	
32	const asObject = (value: unknown): Json | undefined =>
33	  typeof value === "object" && value !== null && !Array.isArray(value)
34	    ? (value as Json)
35	    : undefined;
36	const asArray = (value: unknown): unknown[] =>
37	  Array.isArray(value) ? value : [];
38	const asString = (value: unknown): string =>
39	  typeof value === "string" ? value : "";
40	
41	/** Pulls every video record out of a TikTok API response or embedded page data. */
42	export function extractVideos(json: unknown): TikTokVideo[] {
43	  const root = asObject(json);
44	  if (!root) return [];
45	  const pageScope = asObject(root.__DEFAULT_SCOPE__);
46	  const candidates = pageScope
47	    ? [
48	        asObject(asObject(pageScope["webapp.video-detail"])?.itemInfo)
49	          ?.itemStruct,
50	      ]
51	    : [...asArray(root.itemList), asObject(root.itemInfo)?.itemStruct];
52	  return candidates.flatMap((candidate) => {
53	    const video = toVideo(candidate);
54	    return video ? [video] : [];
55	  });
56	}
57	
58	function toVideo(value: unknown): TikTokVideo | null {
59	  const item = asObject(value);
60	  const video = asObject(item?.video);
61	  const id = asString(item?.id);
62	  if (!item || !video || !/^\d+$/.test(id)) return null;
63	
64	  const captionInfo = asObject(video.claInfo);
65	  const tracks = [
66	    ...asArray(captionInfo?.captionInfos),
67	    ...asArray(video.subtitleInfos),
68	  ].flatMap((entry) => {
69	    const track = toCaptionTrack(entry);
70	    return track ? [track] : [];
71	  });
72	  const reason = captionInfo?.noCaptionReason;
73	  const aiDescription = asString(item.AIGCDescription);
74	
75	  return {
76	    id,
77	    author: asString(asObject(item.author)?.uniqueId),
78	    description: asString(item.desc),
79	    hashtags: asArray(item.textExtra)
80	      .map((tag) => asString(asObject(tag)?.hashtagName))
81	      .filter(Boolean),
82	    onScreenText: asArray(item.stickersOnItem)
83	      .flatMap((sticker) =>
84	        asArray(asObject(sticker)?.stickerText).map(asString),
85	      )
86	      .filter(Boolean),
87	    captionTracks: tracks.filter(
88	      (track, index) =>
89	        tracks.findIndex((other) => other.url === track.url) === index,
90	    ),
91	    noCaptionReason: typeof reason === "number" ? reason : null,
92	    aiLabel: {
93	      labeled: item.IsAigc === true || aiDescription !== "",
94	      description: aiDescription,
95	    },
96	  };
97	}
98	
99	// TikTok lists captions in two places with different field names:
100	// video.claInfo.captionInfos (camelCase) and video.subtitleInfos (PascalCase).
101	// The entry field names come from TikTok pages seen before 2026; only empty
102	// caption lists could be inspected on 2026-10-12, so confirm them on a live video.
103	function toCaptionTrack(value: unknown): CaptionTrack | null {
104	  const entry = asObject(value);
105	  if (!entry) return null;
106	  const url =
107	    asString(entry.url) ||
108	    asString(entry.Url) ||
109	    asString(asArray(entry.urlList)[0]) ||
110	    asString(asArray(entry.UrlList)[0]);
111	  if (!url) return null;
112	  return {
113	    url,
114	    language: asString(entry.language) || asString(entry.LanguageCodeName),
115	    format: (
116	      asString(entry.captionFormat) || asString(entry.Format)
117	    ).toLowerCase(),
118	    autoGenerated: entry.isAutoGen === true || entry.Source === "ASR",
119	    original: entry.isOriginalCaption === true || entry.Source === "ASR",
120	  };
121	}
122	
123	/** Prefers captions in the speaker's own language, then English, then any. */
124	export function pickCaptionTrack(tracks: CaptionTrack[]): CaptionTrack | null {
125	  const readable = tracks.filter(
126	    (track) => track.format === "" || track.format === "webvtt",
127	  );
128	  return (
129	    readable.find((track) => track.original) ??
130	    readable.find((track) => /^en/i.test(track.language)) ??
131	    readable[0] ??
132	    null
133	  );
134	}
135	
136	/**
137	 * Finds which TikTok video a player belongs to. TikTok wraps each player in an
138	 * element whose id ends with the video's id (`xgwrapper-0-7621991999251467550`);
139	 * on a single video's page the id is also in the address (`/@user/video/7621…`).
140	 */
141	export function videoIdFrom(
142	  ancestorIds: string[],
143	  pathname: string,
144	): string | null {
145	  for (const id of ancestorIds) {
146	    const match = /^xgwrapper-\d+-(\d+)$/.exec(id);
147	    if (match) return match[1];
148	  }
149	  return /\/video\/(\d+)/.exec(pathname)?.[1] ?? null;
150	}
151	
152	/** Whether a network response might carry video records worth reading. */
153	export function isTikTokApiUrl(url: string): boolean {
154	  const parsed = parseHttpsUrl(url);
155	  return (
156	    parsed !== null &&
157	    isOnDomain(parsed.hostname, "tiktok.com") &&
158	    parsed.pathname.startsWith("/api/")
159	  );
160	}
161	
162	/** Whether a caption file address points at TikTok's own servers. */
163	export function isTikTokCaptionUrl(url: string): boolean {
164	  const parsed = parseHttpsUrl(url);
165	  return (
166	    parsed !== null &&
167	    CAPTION_DOMAINS.some((domain) => isOnDomain(parsed.hostname, domain))
168	  );
169	}
170	
171	function parseHttpsUrl(url: string): URL | null {
172	  try {
173	    const parsed = new URL(url);
174	    return parsed.protocol === "https:" ? parsed : null;
175	  } catch {
176	    return null;
177	  }
178	}
179	
180	const isOnDomain = (hostname: string, domain: string): boolean =>
181	  hostname === domain || hostname.endsWith(`.${domain}`);
182

1	// Runs inside the TikTok page itself (not the extension's isolated world) so it
2	// can see the video data TikTok's own code downloads. It never changes what
3	// TikTok receives: it reads a copy of each response and hands it to content.ts.
4	import { PAGE_HOOK_SOURCE, type PageHookMessage } from "./messages.ts";
5	import { extractVideos, isTikTokApiUrl } from "./tiktok.ts";
6	
7	function forward(json: unknown): void {
8	  const videos = extractVideos(json);
9	  if (videos.length === 0) return;
10	  const message: PageHookMessage = { source: PAGE_HOOK_SOURCE, videos };
11	  window.postMessage(message, window.location.origin);
12	}
13	
14	const originalFetch = window.fetch;
15	window.fetch = async (...args: Parameters<typeof fetch>) => {
16	  const response = await originalFetch.apply(window, args);
17	  if (isTikTokApiUrl(response.url)) {
18	    // Responses that aren't JSON have nothing for us, so a parse failure is ignored.
19	    response
20	      .clone()
21	      .json()
22	      .then(forward, () => {});
23	  }
24	  return response;
25	};
26	
27	const originalOpen = XMLHttpRequest.prototype.open;
28	XMLHttpRequest.prototype.open = function (
29	  this: XMLHttpRequest,
30	  ...args: unknown[]
31	) {
32	  this.addEventListener("load", () => {
33	    if (isTikTokApiUrl(this.responseURL)) forward(readJson(this));
34	  });
35	  Reflect.apply(originalOpen, this, args);
36	} as typeof XMLHttpRequest.prototype.open;
37	
38	function readJson(request: XMLHttpRequest): unknown {
39	  if (request.responseType === "json") return request.response;
40	  if (request.responseType !== "" && request.responseType !== "text") {
41	    return null;
42	  }
43	  try {
44	    return JSON.parse(request.responseText);
45	  } catch {
46	    return null;
47	  }
48	}
