1	// Runs in the extension's isolated world on tiktok.com. Collects video records
2	// from the page, notices which video starts playing, and (for milestone 1)
3	// prints its transcript and AI label to the browser console.
4	import {
5	  PAGE_HOOK_SOURCE,
6	  type FetchCaptionRequest,
7	  type FetchCaptionResponse,
8	} from "./messages.ts";
9	import {
10	  EMBEDDED_DATA_ELEMENT_ID,
11	  extractVideos,
12	  pickCaptionTrack,
13	  videoIdFrom,
14	  type TikTokVideo,
15	} from "./tiktok.ts";
16	import { parseWebVtt } from "./webvtt.ts";
17	
18	const LOG_PREFIX = "[Fact check]";
19	const DATA_WAIT_MS = 5000;
20	
21	const videosById = new Map<string, TikTokVideo>();
22	const reported = new Set<string>();
23	let waitingForId: string | null = null;
24	
25	function remember(videos: TikTokVideo[]): void {
26	  for (const video of videos) videosById.set(video.id, video);
27	  if (waitingForId && videosById.has(waitingForId)) {
28	    const id = waitingForId;
29	    waitingForId = null;
30	    void report(id);
31	  }
32	}
33	
34	window.addEventListener("message", (event) => {
35	  if (
36	    event.source !== window ||
37	    event.data?.source !== PAGE_HOOK_SOURCE ||
38	    !Array.isArray(event.data.videos)
39	  ) {
40	    return;
41	  }
42	  remember(event.data.videos);
43	});
44	
45	document.addEventListener("DOMContentLoaded", () => {
46	  const embedded = document.getElementById(EMBEDDED_DATA_ELEMENT_ID);
47	  if (!embedded?.textContent) return;
48	  try {
49	    remember(extractVideos(JSON.parse(embedded.textContent)));
50	  } catch {
51	    console.warn(`${LOG_PREFIX} Couldn't read TikTok's page data.`);
52	  }
53	});
54	
55	// "play" doesn't bubble, so listen in the capture phase to hear every video.
56	document.addEventListener(
57	  "play",
58	  (event) => {
59	    if (!(event.target instanceof HTMLVideoElement)) return;
60	    const id = videoIdFrom(ancestorIds(event.target), location.pathname);
61	    if (!id || reported.has(id)) return;
62	    if (videosById.has(id)) {
63	      void report(id);
64	      return;
65	    }
66	    waitingForId = id;
67	    setTimeout(() => {
68	      if (waitingForId !== id) return;
69	      waitingForId = null;
70	      console.warn(
71	        `${LOG_PREFIX} Video ${id} is playing, but its TikTok data wasn't captured.`,
72	      );
73	    }, DATA_WAIT_MS);
74	  },
75	  true,
76	);
77	
78	function ancestorIds(element: Element): string[] {
79	  const ids: string[] = [];
80	  for (let node = element.parentElement; node; node = node.parentElement) {
81	    if (node.id) ids.push(node.id);
82	  }
83	  return ids;
84	}
85	
86	async function report(id: string): Promise<void> {
87	  const video = videosById.get(id);
88	  if (!video || reported.has(id)) return;
89	  reported.add(id);
90	  const transcript = await loadTranscript(video);
91	
92	  const { labeled, description } = video.aiLabel;
93	  console.group(`${LOG_PREFIX} @${video.author} · video ${video.id}`);
94	  console.log(
95	    "TikTok AI label:",
96	    labeled ? `yes${description ? ` ("${description}")` : ""}` : "no",
97	  );
98	  console.log("Caption:", video.description || "(none)");
99	  if (video.onScreenText.length > 0) {
100	    console.log("On-screen text:", video.onScreenText.join(" | "));
101	  }
102	  console.log("Transcript:", transcript);
103	  console.groupEnd();
104	}
105	
106	async function loadTranscript(video: TikTokVideo): Promise<string> {
107	  const track = pickCaptionTrack(video.captionTracks);
108	  if (!track) {
109	    return video.noCaptionReason === null
110	      ? "none"
111	      : `none (TikTok reason code ${video.noCaptionReason})`;
112	  }
113	  const kind = `${track.autoGenerated ? "auto-generated " : ""}captions, ${track.language || "unknown language"}`;
114	  try {
115	    const cues = parseWebVtt(await fetchCaptionFile(track.url));
116	    return `(${kind}) ${cues.map((cue) => cue.text).join(" ") || "[empty]"}`;
117	  } catch (error) {
118	    const reason = error instanceof Error ? error.message : String(error);
119	    return `couldn't load ${kind}: ${reason}`;
120	  }
121	}
122	
123	// Try the request the way TikTok's own player would. If the caption server
124	// refuses requests from the page, the background script fetches it instead.
125	async function fetchCaptionFile(url: string): Promise<string> {
126	  try {
127	    const response = await fetch(url);
128	    if (response.ok) return await response.text();
129	  } catch {
130	    // Blocked by the caption server's cross-origin rules; fall through.
131	  }
132	  const request: FetchCaptionRequest = { type: "fetchCaption", url };
133	  const response: FetchCaptionResponse | undefined =
134	    await chrome.runtime.sendMessage(request);
135	  if (!response) throw new Error("the background script didn't answer");
136	  if (!response.ok) throw new Error(response.error);
137	  return response.text;
138	}
