/** A row needs a look when TypeSafe doubts its due date or disagrees on its status. */
export function needsCheck(
  status: Assignment["status"],
  dueProbability: number,
  openProbability: number,
): boolean {
  if (dueProbability < CONFIDENT) return true;
  if (status === "open") return openProbability < CONFIDENT;
  if (status === "closed") return openProbability > 1 - CONFIDENT;
  return true;
}

