:root {
  color-scheme: light dark;
  --page: #f7f6f2;
  --card: #ffffff;
  --text: #1f1e1b;
  --muted: #6b6a64;
  --line: #e2e0d8;
  --accent: #2f6fd0;
  --accent-text: #ffffff;
  --warn-bg: #fdf1d8;
  --warn-text: #7a4a05;
  --good-text: #2f6b12;
  --danger: #b3261e;
}

@media (prefers-color-scheme: dark) {
  :root {
    --page: #191917;
    --card: #232321;
    --text: #ecebe6;
    --muted: #a3a29b;
    --line: #3a3a36;
    --accent: #6ea2f2;
    --accent-text: #0d1b2e;
    --warn-bg: #4a3510;
    --warn-text: #f6d79a;
    --good-text: #9ccf7d;
    --danger: #f2a49c;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--page);
  color: var(--text);
  font:
    16px/1.5 system-ui,
    sans-serif;
}

.top-bar {
  border-bottom: 1px solid var(--line);
  background: var(--card);
}

.top-bar nav {
  display: flex;
  gap: 4px;
  max-width: 760px;
  margin: 0 auto;
  padding: 8px 16px;
}

.top-bar a {
  padding: 8px 16px;
  border-radius: 8px;
  color: var(--muted);
  text-decoration: none;
  font-weight: 500;
}

.top-bar a[aria-current="page"] {
  background: var(--page);
  color: var(--text);
}

main {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 16px 64px;
}

h1 {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 600;
}

h2 {
  margin: 28px 0 8px;
  font-size: 1.05rem;
  font-weight: 600;
}

.muted {
  color: var(--muted);
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 20px;
}

.plan-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.plan-header .hint {
  margin: 4px 0 0;
  font-size: 0.9rem;
}

button,
.button {
  min-height: 40px;
  padding: 8px 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  color: var(--text);
  font: inherit;
  cursor: pointer;
}

button.primary,
.button.primary {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-text);
}

button:disabled {
  cursor: wait;
  opacity: 0.6;
}

.notice {
  margin: 16px 0 0;
  padding: 12px 16px;
  border-radius: 8px;
  background: var(--card);
  border: 1px solid var(--line);
}

.notice.error {
  border-color: var(--danger);
  color: var(--danger);
}

.notice.good {
  color: var(--good-text);
}

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--line);
}

.list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}

.list .when {
  flex: 0 0 88px;
  color: var(--muted);
  font-size: 0.9rem;
}

.list .what {
  flex: 1;
  min-width: 0;
}

.list .course {
  color: var(--muted);
  font-size: 0.9rem;
}

.tag {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--warn-bg);
  color: var(--warn-text);
  font-size: 0.8rem;
}

.drop-target {
  outline: 2px dashed var(--accent);
  outline-offset: 8px;
  border-radius: 12px;
}

/* Review */
.review {
  margin-top: 16px;
}

.review-row {
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}

.review-row.left-out .fields {
  opacity: 0.55;
}

.review-row .top {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.review-row .match {
  font-size: 0.9rem;
  color: var(--muted);
}

.review-row .match.changed {
  color: var(--good-text);
}

.fields {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  gap: 8px;
  margin-top: 8px;
}

.fields label {
  display: flex;
  flex-direction: column;
  font-size: 0.8rem;
  color: var(--muted);
}

.fields input,
.fields select {
  min-height: 36px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--page);
  color: var(--text);
  font: inherit;
}

.ask {
  margin-top: 8px;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--warn-bg);
  color: var(--warn-text);
}

.ask label {
  margin-right: 16px;
}

.actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}

.error-text {
  color: var(--danger);
  font-size: 0.9rem;
}

details summary {
  cursor: pointer;
  color: var(--muted);
  margin-top: 28px;
}

@media (max-width: 560px) {
  .fields {
