1	// Decides how each imported row relates to what's already saved, so the same
2	// assignment is never saved twice. Code finds the candidates (same name, or
3	// same course with a due date within a day); TypeSafe judges the candidates
4	// whose names differ, like "Connect: Lessico 6" on Canvas and "Lessico- 6".
5	import { noul, TypeSafeClient } from "@typesafe-ai/sdk";
6	import {
7	  shortDate,
8	  STATUS_LABELS,
9	  type Match,
10	  type ReviewRow,
11	  type SavedAssignment,
12	} from "./assignment.ts";
13	import { CONFIDENT, type CheckedAssignment } from "./import-screenshot.ts";
14	
15	const DAY_MS = 24 * 60 * 60 * 1000;
16	
17	/** "Strutture III- 5" and "strutture iii-5" compare equal; accents are ignored. */
18	export function normalizeName(name: string): string {
19	  return name
20	    .normalize("NFKD")
21	    .replace(/[̀-ͯ]/g, "")
22	    .toLowerCase()
23	    .replace(/[^a-z0-9]/g, "");
24	}
25	
26	/** An empty course means the screenshot didn't show one, so it can match any. */
27	const coursesFit = (a: string, b: string) =>
28	  !a || !b || normalizeName(a) === normalizeName(b);
29	
30	const datesClose = (a: string | null, b: string | null) =>
31	  a && b ? Math.abs(Date.parse(a) - Date.parse(b)) <= DAY_MS : a === b;
32	
33	export interface CandidatePair {
34	  imported: CheckedAssignment;
35	  saved: SavedAssignment;
36	}
37	
38	/** Probability, for each pair, that both rows are the same assignment. */
39	export type JudgeSame = (pairs: CandidatePair[]) => Promise<number[]>;
40	
41	export async function reviewImport(
42	  rows: CheckedAssignment[],
43	  saved: SavedAssignment[],
44	  judgeSame: JudgeSame,
45	): Promise<ReviewRow[]> {
46	  const exact = rows.map((row) =>
47	    saved.find(
48	      (candidate) =>
49	        coursesFit(row.course, candidate.course) &&
50	        [candidate.name, ...candidate.aliases].some(
51	          (name) => normalizeName(name) === normalizeName(row.name),
52	        ),
53	    ),
54	  );
55	
56	  const pairs: (CandidatePair & { row: number })[] = [];
57	  rows.forEach((row, index) => {
58	    if (exact[index]) return;
59	    for (const candidate of saved) {
60	      if (
61	        coursesFit(row.course, candidate.course) &&
62	        datesClose(row.dueAt, candidate.dueAt)
63	      ) {
64	        pairs.push({ row: index, imported: row, saved: candidate });
65	      }
66	    }
67	  });
68	  const probabilities = pairs.length > 0 ? await judgeSame(pairs) : [];
69	
70	  return rows.map((row, index) => {
71	    let target = exact[index];
72	    let match: Match = { kind: "new" };
73	    if (!target) {
74	      const best = pairs
75	        .map((pair, k) => ({ ...pair, probability: probabilities[k] }))
76	        .filter((pair) => pair.row === index)
77	        .sort((a, b) => b.probability - a.probability)[0];
78	      if (best && best.probability >= CONFIDENT) target = best.saved;
79	      else if (best && best.probability > 1 - CONFIDENT) {
80	        match = { kind: "ask", id: best.saved.id, savedName: best.saved.name };
81	      }
82	    }
83	    if (target) {
84	      match = { kind: "same", id: target.id, changes: changes(target, row) };
85	    }
86	    // Fill what this screenshot didn't show from what's already saved.
87	    const dueAt = row.dueAt ?? target?.dueAt ?? null;
88	    return {
89	      name: row.name,
90	      course: row.course || target?.course || "",
91	      dueAt,
92	      status: row.status === "unknown" && target ? target.status : row.status,
93	      include: target?.ignored ? false : row.include,
94	      flag:
95	        target?.ignored || (row.flag === "Needs a date" && dueAt)
96	          ? null
97	          : row.flag,
98	      match,
99	    };
100	  });
101	}
102	
103	/** What this import would change about a saved assignment, in words. */
104	function changes(saved: SavedAssignment, row: CheckedAssignment): string[] {
105	  const list: string[] = [];
