// Picks what to do next for the Now page. TypeSafe's part is the time
// estimate; the order is plain code using a standard scheduling rule, least
// slack first: the task whose latest sensible start time comes soonest.
import type { SavedAssignment } from "./assignment.ts";

/** Used until TypeSafe has estimated a task. */
const DEFAULT_MINUTES = 30;
// ponytail: fixed slack (half again the work time, at least 15 minutes); the
// learning milestone replaces this with Dylan's real pace.
const SLACK_FACTOR = 1.5;
const MIN_SLACK_MINUTES = 15;

export interface Pick {
  assignment: SavedAssignment;
  minutes: number;
  /** The latest start that still finishes on time, with some slack. */
  startBy: Date;
}

/** Everything that can be worked on now, least time to spare first. */
export function rankTasks(assignments: SavedAssignment[], now: Date): Pick[] {
  return assignments
    .filter(
      (assignment) =>
        !assignment.ignored &&
        (assignment.status === "open" || assignment.status === "unknown") &&
        assignment.dueAt !== null &&
        Date.parse(assignment.dueAt) > now.getTime(),
    )
    .map((assignment) => {
      const minutes = assignment.estimateMinutes ?? DEFAULT_MINUTES;
      const withSlack = Math.max(
        minutes * SLACK_FACTOR,
        minutes + MIN_SLACK_MINUTES,
      );
      const due = Date.parse(assignment.dueAt!);
      return {
        assignment,
        minutes,
        startBy: new Date(due - withSlack * 60_000),
      };
    })
    .sort((a, b) => a.startBy.getTime() - b.startBy.getTime());
}

/** For "Too tired?": the quickest other task, if one is quicker. */
export function smallerTask(ranked: Pick[], current: Pick): Pick | null {
  const quicker = ranked
    .filter((pick) => pick.minutes < current.minutes)
    .sort(
      (a, b) =>
        a.minutes - b.minutes || a.startBy.getTime() - b.startBy.getTime(),
    );
  return quicker[0] ?? null;
}

/** "today at 9:40 PM", "tomorrow at …", "Friday at …", or "Oct 30 at …". */
export function describeWhen(date: Date, now: Date): string {
  const time = date.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
  });
  const startOfDay = (d: Date) =>
    new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
  const days = Math.round((startOfDay(date) - startOfDay(now)) / 86_400_000);
  const day =
    days === 0
      ? "today"
      : days === 1
        ? "tomorrow"
        : days > 1 && days < 7
          ? date.toLocaleDateString("en-US", { weekday: "long" })
          : date.toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
            });
  return `${day} at ${time}`;
}

export type PickKind = "first" | "next" | "smaller";

/** One sentence on why this task, which is always true for how it was picked. */
export function reasonFor(pick: Pick, kind: PickKind, now: Date): string {
  const work = `about ${pick.minutes} min of work`;
  const due = `due ${describeWhen(new Date(pick.assignment.dueAt!), now)}`;
  if (pick.startBy <= now) {
    return `It's ${due} and takes ${work.replace("about ", "about ")}, so start now to finish on time.`;
  }
  if (kind === "smaller") return `The quickest thing on your list: ${work}, ${due}.`;
  if (kind === "next") return `Next with the least time to spare: ${due}, ${work}.`;
  return `It has the least time to spare of everything on your list: ${due}, ${work}.`;
}

