import assert from "node:assert/strict";
import test from "node:test";
import type { SavedAssignment, Status } from "../src/assignment.ts";
import { rankTasks, reasonFor, smallerTask } from "../src/now.ts";

// Thursday Oct 22, 2026, 6 pm in whatever time zone the tests run in.
const now = new Date(2026, 9, 22, 18, 0);
let nextId = 1;
const task = (
  name: string,
  due: Date | null,
  estimateMinutes: number | null,
  status: Status = "open",
): SavedAssignment => ({
  id: nextId++,
  name,
  course: "ITAL 101",
  dueAt: due && due.toISOString(),
  status,
  aliases: [],
  ignored: false,
  estimateMinutes,
});

const discussione = task("Discussione 4", new Date(2026, 9, 23, 23, 59), 30);
const physics = task("Four-year plan", new Date(2026, 11, 11, 23, 59), 150);
const voiceBoard = task("Voice Board 5", new Date(2026, 9, 23, 23, 59), 10);
const names = (picks: { assignment: SavedAssignment }[]) =>
  picks.map((pick) => pick.assignment.name);

test("puts the task with the least time to spare first", () => {
  const ranked = rankTasks([physics, voiceBoard, discussione], now);
  assert.deepEqual(names(ranked), ["Discussione 4", "Voice Board 5", "Four-year plan"]);
  // 30 min of work plus slack (45 min) before 11:59 pm.
  assert.equal(
    ranked[0].startBy.getTime(),
    new Date(2026, 9, 23, 23, 14).getTime(),
  );
});

test("leaves out work that can't be done now", () => {
  const ranked = rankTasks(
    [
      task("Discussione 5", new Date(2026, 9, 30, 23, 59), 30, "not_open_yet"),
      task("Strutture II", new Date(2026, 9, 25, 23, 59), 30, "closed"),
      task("Strutture III", new Date(2026, 9, 20, 23, 59), 30),
      task("Midterm Exam", null, 360),
      discussione,
    ],
    now,
  );
  assert.deepEqual(names(ranked), ["Discussione 4"], "not open, done, past, undated");
});

test("an unestimated task counts as 30 minutes", () => {
  const [pick] = rankTasks([task("New thing", new Date(2026, 9, 23, 23, 59), null)], now);
  assert.equal(pick.minutes, 30);
});

test("'Too tired?' offers the quickest task, or nothing if this is already it", () => {
  const ranked = rankTasks([physics, voiceBoard, discussione], now);
  assert.equal(smallerTask(ranked, ranked[0])?.assignment.name, "Voice Board 5");
  assert.equal(smallerTask(ranked, ranked[1]), null);
});

test("the reason says to start now when time is short", () => {
  const ranked = rankTasks([discussione], new Date(2026, 9, 23, 23, 30));
  assert.match(
    reasonFor(ranked[0], "first", new Date(2026, 9, 23, 23, 30)),
    /start now/,
  );
  const early = rankTasks([discussione], now);
  assert.match(reasonFor(early[0], "first", now), /least time to spare.*tomorrow at 11:59/);
});
EOF
