          : "Add a screenshot of an assignments page on your Plan, and this page will pick what to do first.",
      ),
      planLink,
    );
  }

  const queue = ranked.filter((pick) => !state.skipped.has(pick.assignment.id));
  let pick = state.override
    ? ranked.find((p) => p.assignment.id === state.override!.id)
    : undefined;
  let kind: PickKind = state.override?.kind ?? "first";
  if (!pick) {
