/** For "Too tired?": the shortest other session, if one is shorter. */
export function smallerItem(
  items: WorkItem[],
  current: WorkItem,
): WorkItem | null {
  const shorter = items
    .filter((item) => item.minutes < current.minutes)
    .sort((a, b) => a.minutes - b.minutes);
