    .filter((a) => !isDueSoon(a))
    .map((assignment) => {
      const remaining = remainingOf(assignment);
      const slack = remaining >= BIG_TASK ? 2 : 1;
      const lastDay = addDays(startOfDay(new Date(assignment.dueAt!)), -slack);
      return {
        assignment,
