  const history = buildHistory(
    [
      assignment("Discussione 4", { closedAt: new Date(2026, 9, 22, 21, 0) }),
      assignment("Four-year plan", {
        sessions: [
          session(1, 25, new Date(2026, 9, 22, 22, 0)),
