// One-off cleanup after the Canvas course-code bug: removes assignments saved
// twice (same name, same course once codes are compared), keeping the older
// row, then renames courses to their codes. Pass --apply to change anything.
import { DatabaseSync } from "node:sqlite";
import { courseCode } from "../../../../../../../OneDrive/Desktop/cs124/Project-Fall2026-Dilpickl-67565383/src/assignment.ts";
import { normalizeName } from "../../../../../../../OneDrive/Desktop/cs124/Project-Fall2026-Dilpickl-67565383/src/match.ts";

const [path, flag] = process.argv.slice(2);
const apply = flag === "--apply";
const db = new DatabaseSync(path);
const rows = db
  .prepare("SELECT id, name, course FROM assignments ORDER BY id")
  .all() as { id: number; name: string; course: string }[];
const logged = new Set(
  (db.prepare("SELECT DISTINCT assignment_id FROM work_log").all() as { assignment_id: number }[]).map((r) => r.assignment_id),
);

const firstSeen = new Map<string, number>();
const duplicates: number[] = [];
for (const row of rows) {
  const key = `${normalizeName(courseCode(row.course))}|${normalizeName(row.name)}`;
  const original = firstSeen.get(key);
  if (original === undefined) firstSeen.set(key, row.id);
  else {
    if (logged.has(row.id)) throw new Error(`Duplicate ${row.id} has logged work; merge by hand`);
    duplicates.push(row.id);
  }
}
const renames = rows.filter((row) => courseCode(row.course) !== row.course);
console.log(`duplicates to remove: ${duplicates.length} (ids ${duplicates.join(", ")})`);
console.log(`courses to rename: ${[...new Set(renames.map((r) => `${r.course} -> ${courseCode(r.course)}`))].join("; ")}`);

if (apply) {
  db.exec("BEGIN");
  for (const id of duplicates) db.prepare("DELETE FROM assignments WHERE id = ?").run(id);
  for (const row of renames) {
    db.prepare("UPDATE assignments SET course = ? WHERE id = ?").run(courseCode(row.course), row.id);
  }
  db.exec("COMMIT");
  console.log("applied");
}

